// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance + 1 ether);
        vm.deal(address(this), 10 ether);
        vm.deal(actor, 0);
        c = new MyContract();
        vm.startPrank(actor);
        // fund c through its own owner entry: owner is msg.sender of setUp, i.e. this test contract
        vm.stopPrank();
        Recorder r = new Recorder();
        vm.deal(address(c), amount);
        bool ok;
        bool sent; try c.sendTo(address(r), amount) { sent = true; } catch { sent = false; }
        ok = sent;
        // Rule: a receiver that consumes more than the 2300 gas stipend in its
        // receive() must make sendTo fail (transfer propagates out-of-gas as revert).
        assertTrue(!ok, "sendTo to a gas-hungry recorder must revert");
    }

    receive() external payable {}
}

contract Recorder {
    uint256 public hits;
    receive() external payable {
        for (uint256 i = 0; i < 10; i++) {
            hits += 1;
        }
    }
}
